def font_path(names):
    root=Path(r"C:\Windows\Fonts")
    for n in names:
        p=root/n
        if p.exists(): return str(p)
FONT=font_path(["msyh.ttc","msyh.ttf","simhei.ttf"])
FONT_BOLD=font_path(["msyhbd.ttc","msyhbd.ttf","simhei.ttf"]) or FONT

def set_run(run,size=10.5,bold=False,color=TEXT,italic=False):
    run.font.name="Microsoft YaHei"; run.font.size=Pt(size); run.bold=bold; run.italic=italic
    run.font.color.rgb=RGBColor.from_string(color); run._element.get_or_add_rPr().rFonts.set(qn("w:eastAsia"),"Microsoft YaHei")

def shade(cell,fill):
    tcPr=cell._tc.get_or_add_tcPr(); node=tcPr.find(qn("w:shd"))
    if node is None: node=OxmlElement("w:shd"); tcPr.append(node)
    node.set(qn("w:fill"),fill)

def borders(cell,color=LINE):
    tcPr=cell._tc.get_or_add_tcPr(); bd=tcPr.first_child_found_in("w:tcBorders")
    if bd is None: bd=OxmlElement("w:tcBorders"); tcPr.append(bd)
    for edge in ("top","start","bottom","end","insideH","insideV"):
        e=bd.find(qn(f"w:{edge}"))
        if e is None: e=OxmlElement(f"w:{edge}"); bd.append(e)
        e.set(qn("w:val"),"single"); e.set(qn("w:sz"),"6"); e.set(qn("w:color"),color)

def margins(cell,top=90,start=110,bottom=90,end=110):
    tcPr=cell._tc.get_or_add_tcPr(); mar=tcPr.first_child_found_in("w:tcMar")
    if mar is None: mar=OxmlElement("w:tcMar"); tcPr.append(mar)
    for n,v in (("top",top),("start",start),("bottom",bottom),("end",end)):
        x=mar.find(qn(f"w:{n}"))
        if x is None: x=OxmlElement(f"w:{n}"); mar.append(x)
        x.set(qn("w:w"),str(v)); x.set(qn("w:type"),"dxa")

def repeat_header(row):
    pr=row._tr.get_or_add_trPr(); h=OxmlElement("w:tblHeader"); h.set(qn("w:val"),"true"); pr.append(h)

def prevent_row_split(row):
    pr=row._tr.get_or_add_trPr(); x=OxmlElement("w:cantSplit"); x.set(qn("w:val"),"true"); pr.append(x)

def heading(doc,text,level=1):
    p=doc.add_heading(text,level=level); p.paragraph_format.keep_with_next=True; return p

def body(doc,text,lead=None):
    p=doc.add_paragraph(); p.paragraph_format.space_after=Pt(5); p.paragraph_format.line_spacing=1.3
    if lead and text.startswith(lead):
        r=p.add_run(lead); set_run(r,10.3,True)
        r=p.add_run(text[len(lead):]); set_run(r,10.3)
    else: r=p.add_run(text); set_run(r,10.3)
    return p

def marker(doc,label,text,color=NAVY):
    p=doc.add_paragraph(); p.paragraph_format.space_before=Pt(5); p.paragraph_format.space_after=Pt(5); p.paragraph_format.line_spacing=1.25
    r=p.add_run(label+"："); set_run(r,10.3,True,color)
    r=p.add_run(text); set_run(r,10.3)
    return p

def bullets(doc,items):
    for item in items:
        p=doc.add_paragraph(style="List Bullet"); p.paragraph_format.space_after=Pt(3); p.paragraph_format.line_spacing=1.22
        r=p.add_run(item); set_run(r,10.0)

def steps(doc,items):
    for i,item in enumerate(items,1):
        p=doc.add_paragraph(); p.paragraph_format.left_indent=Cm(.55); p.paragraph_format.first_line_indent=Cm(-.55); p.paragraph_format.space_after=Pt(3); p.paragraph_format.line_spacing=1.22
        r=p.add_run(f"{i}.  {item}"); set_run(r,10.0)

def table(doc,headers,rows,widths=None,font=8.2):
    t=doc.add_table(rows=1,cols=len(headers)); t.style="Table Grid"; t.alignment=WD_TABLE_ALIGNMENT.CENTER; t.autofit=False
    repeat_header(t.rows[0])
    for j,h in enumerate(headers):
        c=t.rows[0].cells[j]; c.text=str(h); c.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER; shade(c,NAVY); borders(c); margins(c)
        for p in c.paragraphs:
            p.alignment=WD_ALIGN_PARAGRAPH.CENTER
            for r in p.runs:set_run(r,font,True,"FFFFFF")
    for i,row in enumerate(rows):
        new_row=t.add_row(); prevent_row_split(new_row); cs=new_row.cells
        for j,v in enumerate(row):
            cs[j].text=str(v); cs[j].vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER; borders(cs[j]); margins(cs[j])
            if i%2:shade(cs[j],PALE)
            for p in cs[j].paragraphs:
                p.paragraph_format.space_after=Pt(0); p.paragraph_format.line_spacing=1.05
                if len(str(v))<=10:p.alignment=WD_ALIGN_PARAGRAPH.CENTER
                for r in p.runs:set_run(r,font)
    if widths:
        for row in t.rows:
            for j,w in enumerate(widths): row.cells[j].width=Cm(w)
    doc.add_paragraph().paragraph_format.space_after=Pt(1)
    return t

def hyperlink(p,text,url):
    rid=p.part.relate_to(url,"http://schemas.openxmlformats.org/officeDocument/2006/relationships/hyperlink",is_external=True)
    h=OxmlElement("w:hyperlink"); h.set(qn("r:id"),rid); r=OxmlElement("w:r"); rp=OxmlElement("w:rPr")
    color=OxmlElement("w:color"); color.set(qn("w:val"),"1F4E79"); rp.append(color)
    u=OxmlElement("w:u"); u.set(qn("w:val"),"single"); rp.append(u)
    rf=OxmlElement("w:rFonts"); rf.set(qn("w:eastAsia"),"Microsoft YaHei"); rp.append(rf)
    r.append(rp); tx=OxmlElement("w:t"); tx.text=text; r.append(tx); h.append(r); p._p.append(h)

def add_toc(doc):
    p=doc.add_paragraph(); p.alignment=WD_ALIGN_PARAGRAPH.LEFT
    r=OxmlElement("w:r"); begin=OxmlElement("w:fldChar"); begin.set(qn("w:fldCharType"),"begin"); r.append(begin); p._p.append(r)
    r=OxmlElement("w:r"); instr=OxmlElement("w:instrText"); instr.set(qn("xml:space"),"preserve"); instr.text=' TOC \\o "1-3" \\h \\z \\u '; r.append(instr); p._p.append(r)
    r=OxmlElement("w:r"); sep=OxmlElement("w:fldChar"); sep.set(qn("w:fldCharType"),"separate"); r.append(sep); p._p.append(r)
    rr=p.add_run("打开文件后更新目录即可显示完整页码"); set_run(rr,10,False,"666666")
    r=OxmlElement("w:r"); end=OxmlElement("w:fldChar"); end.set(qn("w:fldCharType"),"end"); r.append(end); p._p.append(r)

def flow_image(name,title,nodes,subline=""):
    w=2200; cols=min(6,len(nodes)); rows=(len(nodes)+cols-1)//cols; h=330+rows*260
    im=Image.new("RGB",(w,h),"white"); d=ImageDraw.Draw(im)
    ft=ImageFont.truetype(FONT_BOLD,56); fn=ImageFont.truetype(FONT_BOLD,31); fs=ImageFont.truetype(FONT,25)
    d.text((1100,45),title,font=ft,fill="#111111",anchor="ma")
    if subline:d.text((1100,115),subline,font=fs,fill="#555555",anchor="ma")
    gap=32; bw=(w-180-gap*(cols-1))//cols; bh=145
    for i,node in enumerate(nodes):
        row=i//cols; col=i%cols
        if row%2==1: col=cols-1-col
        x=90+col*(bw+gap); y=190+row*260
        d.rounded_rectangle((x,y,x+bw,y+bh),radius=20,fill="#F4F7FB",outline="#17365D",width=4)
        lines=node.split("\n")
        for k,line in enumerate(lines):d.text((x+bw/2,y+bh/2+(k-(len(lines)-1)/2)*38),line,font=fn if len(lines)==1 else fs,fill="#20242C",anchor="mm")
        if i<len(nodes)-1:
            nx=i+1; nr=nx//cols; nc=nx%cols
            if nr%2==1:nc=cols-1-nc
            if nr==row:
                if col<nc: a=(x+bw+5,y+bh/2); b=(x+bw+gap-5,y+bh/2)
                else:a=(x-5,y+bh/2); b=(x-gap+5,y+bh/2)
            else:a=(x+bw/2,y+bh+5); b=(x+bw/2,y+250)
            d.line((*a,*b),fill="#548235",width=8)
    p=IMGDIR/f"{name}.png"; im.save(p); return p

